import sys
import openpyxl


def clean_value(value):
    """Return numeric value keeping digits and decimal points, removing others."""
    if value is None:
        return value
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, bool):
        return value
    # Extract digits and decimal points
    s = str(value)
    parts = re.findall(r'[0-9]+(?:\.[0-9]*)?|\.[0-9]+', s)
    clean = ''.join(parts)
    if clean == '':
        return ''
    try:
        return float(clean)
    except ValueError:
        return clean


def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Sheet1']

    for col in range(1, 9):  # A1:H1
        cell = ws.cell(row=1, column=col)
        cell.value = clean_value(cell.value)

    wb.save(output_path)
    print(f"Saved to {output_path}")


